9	
10	/**
11	 * Fluent DSL per descrivere un attributo PIM tipizzato.
12	 *
13	 * Esempi:
14	 *   TypeBuilder::make(Type::Decimal)->unit('mm')->required()->filterable()->min(0)->max(2000)
15	 *   TypeBuilder::make(Type::Enum)->options(['oak', 'walnut', 'mahogany'])->filterable()
16	 *   TypeBuilder::make(Type::String)->translatable()
17	 *   TypeBuilder::make(Type::String)->required()->unique()  // es. SKU
18	 */
19	class TypeBuilder
20	{
21	    /** @var array<string, mixed> */
22	    private array $modifiers = [];
23	
24	    /** @var list<string> */
25	    private array $options = [];
26	
27	    private function __construct(private readonly Type $kind)
28	    {
29	    }
30	
31	    public static function make(Type $kind): self
32	    {
33	        return new self($kind);
34	    }
35	
36	    /**
37	     * @param list<string> $options chiavi canoniche, label tradotte a display time
38	     */
39	    public function options(array $options): self
40	    {
41	        $this->options = $options;
42	
43	        return $this;
44	    }
45	
46	    public function required(): self
47	    {
48	        $this->modifiers['required'] = true;
49	
50	        return $this;
51	    }
52	
53	    /**
54	     * Il valore dell'attributo deve essere univoco tra le righe dell'entità.
55	     *
56	     * La regola Laravel concreta (Rule::unique sul path JSON, con ignore del
57	     * record in update) viene costruita da AttributeSchema::validationRules(),
58	     * che conosce tabella e colonna JSON del modello. toValidationRules() non
59	     * la emette: qui manca quel contesto.
60	     */
61	    public function unique(): self
62	    {
63	        $this->modifiers['unique'] = true;
64	
65	        return $this;
66	    }
67	
68	    public function min(int|float $value): self
69	    {
70	        $this->modifiers['min'] = $value;
71	
72	        return $this;
73	    }
74	
75	    public function max(int|float $value): self
76	    {
77	        $this->modifiers['max'] = $value;
78	
79	        return $this;
80	    }
81	
82	    public function regex(string $pattern): self
83	    {
84	        $this->modifiers['regex'] = $pattern;
85	
86	        return $this;
87	    }
88	
89	    public function unit(string $unit): self
90	    {
91	        $this->modifiers['unit'] = $unit;
92	
93	        return $this;
94	    }
95	
96	    public function translatable(): self
97	    {
98	        $this->modifiers['translatable'] = true;
99	
100	        return $this;
101	    }
102	
103	    public function filterable(): self
104	    {
105	        $this->modifiers['filterable'] = true;
106	
107	        return $this;
108	    }
109	
110	    public function searchable(): self
111	    {
112	        $this->modifiers['searchable'] = true;
113	
114	        return $this;
115	    }
116	
117	    public function kind(): Type
118	    {
119	        return $this->kind;
120	    }
121	
122	    public function isRequired(): bool
123	    {
124	        return (bool) ($this->modifiers['required'] ?? false);
125	    }
126	
127	    public function isUnique(): bool
128	    {
129	        return (bool) ($this->modifiers['unique'] ?? false);
130	    }
131	
132	    public function isTranslatable(): bool
133	    {
134	        return (bool) ($this->modifiers['translatable'] ?? false);
135	    }
136	
137	    public function isFilterable(): bool
138	    {
139	        return (bool) ($this->modifiers['filterable'] ?? false);
140	    }
141	
142	    public function isSearchable(): bool
143	    {
144	        return (bool) ($this->modifiers['searchable'] ?? false);
145	    }
146	
147	    public function getUnit(): ?string
148	    {
149	        $unit = $this->modifiers['unit'] ?? null;
150	
151	        return is_string($unit) ? $unit : null;
152	    }
153	
154	    public function getMin(): int|float|null
155	    {
156	        $min = $this->modifiers['min'] ?? null;
157	
158	        return is_int($min) || is_float($min) ? $min : null;
159	    }
160	
161	    public function getMax(): int|float|null
162	    {
163	        $max = $this->modifiers['max'] ?? null;
164	
165	        return is_int($max) || is_float($max) ? $max : null;
166	    }
167	
168	    /** @return list<string> */
169	    public function getOptions(): array
170	    {
171	        return $this->options;
172	    }
173	
174	    /**
175	     * Regole di validazione Laravel derivate dai modificatori.
176	     * La regola unique è invece costruita in AttributesSchema, per avere
177	     * consapevolezza della tabella e  della colonna su cui agire.
178	     *
179	     * @return list<mixed>
180	     */
181	    public function toValidationRules(): array
182	    {
183	        $rules = [$this->isRequired() ? 'required' : 'nullable'];
184	
185	        $rules[] = match ($this->kind) {
186	            Type::String, Type::Text => 'string',
187	            Type::Int => 'integer',
188	            Type::Decimal => 'numeric',
189	            Type::Bool => 'boolean',
190	            Type::Date => 'date',
191	            Type::Enum => Rule::in($this->options),
192	        };
193	
194	        $min = $this->getMin();
195	        if ($min !== null) {
196	            $rules[] = 'min:' . $min;
197	        }
198	
199	        $max = $this->getMax();
200	        if ($max !== null) {
201	            $rules[] = 'max:' . $max;
202	        }
203	
204	        $regex = $this->modifiers['regex'] ?? null;
205	        if (is_string($regex)) {
206	            $rules[] = 'regex:' . $regex;
207	        }
208	
209	        return $rules;
210	    }
211	}
