5	namespace AtrioTeam\DigitalHub\Api\Http\Controllers;
6	
7	use AtrioTeam\DigitalHub\Api\ApiResourceRegistry;
8	use Illuminate\Contracts\Support\Responsable;
9	use Illuminate\Database\Eloquent\Builder;
10	use Illuminate\Database\Eloquent\Model;
11	use Illuminate\Http\Request;
12	use Symfony\Component\HttpKernel\Exception\NotFoundHttpException;
13	
14	/**
15	 * Controller unico dell'API esterna di lettura (roadmap #24): l'entità arriva
16	 * come slug di route ed è risolta dal {@see ApiResourceRegistry}, che il
17	 * template popola.
18	 *
19	 * 1. La route (GET {resource} / GET {resource}/{identifier}) passa lo slug come parametro $resource a index/show.
20	 * 2. guardResource() chiede al registry has($resource) — se lo slug non è dichiarato in config('digital-hub.api.resources'), 404 (non 500: uno slug sconosciuto è "risorsa inesistente" dal punto di vista del client).
21	 * 3. query() chiede al registry newModel($resource) (istanzia il model Eloquent dichiarato) ed eagerLoads($resource) (il with opzionale, es. ['category1'] per categories-2).
22	 * 4. Applica i filtri generici (updated_since, paginazione) sulla query così ottenuta — il controller non sa nulla del modello specifico, lavora solo su Builder.
23	 * 5. Prima di restituire, chiede al registry jsonResourceClass($resource) per sapere quale JsonResource avvolge il risultato (Category1Resource, Category2Resource, DesignerResource, ecc.) — è quella classe a decidere la forma del payload. *
24	 *
25	 * La paginazione è cursor-less (page/per_page) perché il consumatore itera fino
26	 * all'ultima pagina, non naviga.
27	 */
28	class ApiResourceController
29	{
30	    public function __construct(private readonly ApiResourceRegistry $registry)
31	    {
32	    }
33	
34	    public function index(Request $request, string $resource): Responsable
35	    {
36	        $this->guardResource($resource);
37	
38	        /** @var array<string, mixed> $validated */
39	        $validated = $request->validate([
40	            'updated_since' => ['sometimes', 'date'],
41	            'per_page' => ['sometimes', 'integer', 'min:1', 'max:200'],
42	        ]);
43	
44	        $query = $this->query($resource);
45	
46	        if (isset($validated['updated_since'])) {
47	            $query->where('updated_at', '>=', $validated['updated_since']);
48	        }
49	
50	        $perPage = $validated['per_page'] ?? config('digital-hub.api.per_page', 50);
51	        $perPage = is_numeric($perPage) ? (int) $perPage : 50;
52	
53	        $jsonResource = $this->registry->jsonResourceClass($resource);
54	
55	        return $jsonResource::collection(
56	            $query->orderBy($query->getModel()->getKeyName())->paginate($perPage)->withQueryString(),
57	        );
58	    }
59	
60	    /**
61	     * `{identifier}` è l'id numerico oppure il `global_id` (`{table}:{id}`), che
62	     * è la chiave di join cross-sistema con il CMS (design admin, Parte 1).
63	     */
64	    public function show(string $resource, string $identifier): Responsable
65	    {
66	        $this->guardResource($resource);
67	
68	        $query = $this->query($resource);
69	        $model = $query->getModel();
70	
71	        $record = ctype_digit($identifier)
72	            ? $query->find($identifier)
73	            : $query->where($model->qualifyColumn('global_id'), $identifier)->first();
74	
75	        if (! $record instanceof Model) {
76	            throw new NotFoundHttpException('Record non trovato.');
77	        }
78	
79	        $jsonResource = $this->registry->jsonResourceClass($resource);
80	
81	        return new $jsonResource($record);
82	    }
83	
84	    /**
85	     * @return Builder<Model>
86	     */
87	    private function query(string $resource): Builder
88	    {
89	        return $this->registry->newModel($resource)->newQuery()
90	            ->with($this->registry->eagerLoads($resource));
91	    }
92	
93	    /**
94	     * Slug non dichiarato = 404, non 500: dal punto di vista del client è una
95	     * risorsa che non esiste.
96	     */
97	    private function guardResource(string $resource): void
98	    {
99	        if (! $this->registry->has($resource)) {
100	            throw new NotFoundHttpException("Risorsa [{$resource}] non esposta dall'API.");
101	        }
102	    }
103	}
