21	     * @param Closure(Request): Response $next
22	     */
23	    public function handle(Request $request, Closure $next): Response
24	    {
25	        $requested = $request->query('locale');
26	        $supported = array_keys((array) config('digital-hub.locales', []));
27	
28	        if (is_string($requested) && in_array($requested, $supported, true)) {
29	            app()->setLocale($requested);
30	        }
31	
32	        return $next($request);
33	    }
34	}
