 "info": {
  "name": "Atmosphera Hub — API esterna (#24)",
  "description": "API consumata in pull dai CMS a valle (il primo è atmosphera-admin). Di lettura, tranne la dichiarazione di utilizzo di un asset (#34), che è il modo in cui il client ottiene l'URL pubblico di un file.\n\nAuth: `Authorization: Bearer {{apiToken}}` — token di servizio da `DIGITAL_HUB_API_TOKENS`.\nLingua: `?locale=` (ristretta a `config('digital-hub.locales')`).\nChiave di join cross-sistema: `global_id` ({table}:{id}), non l'id locale.\n\nLa cartella \"Contratto\" contiene i casi di errore: sono parte del contratto verso il client, non scarti.\nRunnabile con Collection Runner o newman; l'ordine conta solo per la cattura di `{{globalId}}` nella prima richiesta.",
  "schema": "https://schema.getpostman.com/json/collection/v2.1.0/collection.json"
 },
 "auth": {
  "type": "bearer",
  "bearer": [
   {
    "key": "token",
    "value": "{{apiToken}}",
    "type": "string"
   }
  ]
 },
 "variable": [
  {
   "key": "resource",
   "value": "designers",
   "description": "Slug dichiarato in config('digital-hub.api.resources')"
  },
  {
   "key": "assetGlobalId",
   "value": "media:1",
   "description": "global_id di un asset esistente a DB (colonna media.global_id)"
  },
  {
   "key": "ownerGlobalId",
   "value": "products:1",
   "description": "global_id del record proprietario per il filtro ?owner="
  },
  {
   "key": "category1GlobalId",
   "value": "",
   "description": "Catturato dalla lista Categorie (categories-1)"
  },
  {
   "key": "category2GlobalId",
   "value": "",
   "description": "Catturato dalla lista Collezioni (categories-2)"
  }
 ],
 "item": [
  {
   "name": "Lettura",
   "item": [
    {
     "name": "Lista designer",
     "event": [
      {
       "listen": "test",
       "script": {
        "type": "text/javascript",
        "exec": [
         "pm.test('200', () => pm.response.to.have.status(200));",
         "const body = pm.response.json();",
         "pm.test('ha data + meta di paginazione', () => {",
         "    pm.expect(body).to.have.property('data');",
         "    pm.expect(body.meta).to.have.property('total');",
         "});",
         "pm.test('ogni record espone il global_id come chiave di join', () => {",
         "    body.data.forEach(r => pm.expect(r.global_id, 'global_id').to.be.a('string'));",
         "});",
         "// Cattura il primo global_id per le richieste successive.",
         "if (body.data.length > 0) {",
         "    pm.collectionVariables.set('globalId', body.data[0].global_id);",
         "    pm.collectionVariables.set('recordId', String(body.data[0].global_id).split(':')[1]);",
         "} else {",
         "    console.warn('Nessun designer nel DB: le richieste per identifier daranno 404.');",
         "}"
        ]
       }
      }
     ],
     "request": {
      "method": "GET",
      "header": [
       {
        "key": "Accept",
        "value": "application/json"
       }
      ],
      "url": {
       "raw": "{{baseUrl}}/api/v1/{{resource}}",
       "host": [
        "{{baseUrl}}"
       ],
       "path": [
        "api",
        "v1",
        "{{resource}}"
       ]
      },
      "description": "Prima pagina. `name` esce già risolto nella lingua di default dell'app, non come mappa translatable."
     }
    },
    {
     "name": "Lista in inglese (?locale=en)",
     "event": [
      {
       "listen": "test",
       "script": {
        "type": "text/javascript",
        "exec": [
         "pm.test('200', () => pm.response.to.have.status(200));",
         "pm.test('name è una stringa risolta, non una mappa lingua=>valore', () => {",
         "    const data = pm.response.json().data;",
         "    if (data.length === 0) { pm.expect.fail('Nessun designer nel DB'); }",
         "    pm.expect(data[0].name).to.satisfy(v => v === null || typeof v === 'string');",
         "});"
        ]
       }
      }
     ],
     "request": {
      "method": "GET",
      "header": [
       {
        "key": "Accept",
        "value": "application/json"
       }
      ],
      "url": {
       "raw": "{{baseUrl}}/api/v1/{{resource}}?locale=en",
       "host": [
        "{{baseUrl}}"
       ],
       "path": [
        "api",
        "v1",
        "{{resource}}"
       ],
       "query": [
        {
         "key": "locale",
         "value": "en"
        }
       ]
      }
     }
    },
    {
     "name": "Singolo per global_id",
     "event": [
      {
       "listen": "test",
       "script": {
        "type": "text/javascript",
        "exec": [
         "pm.test('200', () => pm.response.to.have.status(200));",
         "pm.test('è il record richiesto', () => {",
         "    pm.expect(pm.response.json().data.global_id).to.eql(pm.collectionVariables.get('globalId'));",
         "});"
        ]
       }
      }
     ],
     "request": {
      "method": "GET",
      "header": [
       {
        "key": "Accept",
        "value": "application/json"
       }
      ],
      "url": {
       "raw": "{{baseUrl}}/api/v1/{{resource}}/{{globalId}}",
