   "name": "Asset — lettura (media manager, #24)",
   "description": "Sfogliare e scegliere un asset: è il prerequisito del media manager del CMS a valle, e ciò che precede la pubblicazione della cartella successiva.\n\nEspone solo le collection dichiarate in config('digital-hub.api.asset_collections'): la tabella media ospita anche media che asset non sono.",
   "item": [
    {
     "name": "Lista asset",
     "event": [
      {
       "listen": "test",
       "script": {
        "type": "text/javascript",
        "exec": [
         "pm.test('200', () => pm.response.to.have.status(200));",
         "const body = pm.response.json();",
         "pm.test('ha data + meta di paginazione', () => {",
         "    pm.expect(body).to.have.property('data');",
         "    pm.expect(body.meta).to.have.property('total');",
         "});",
         "pm.test('ogni asset porta ci\\u00f2 che serve a mostrarlo e a decidere se riscaricarlo', () => {",
         "    body.data.forEach(a => {",
         "        pm.expect(a.global_id, 'global_id').to.be.a('string');",
         "        pm.expect(a, 'file_hash').to.have.property('file_hash');",
         "        pm.expect(a.download_url, 'download_url').to.be.a('string');",
         "    });",
         "});",
         "pm.test('public_url \\u00e8 valorizzato solo per gli asset pubblicati', () => {",
         "    body.data.forEach(a => {",
         "        if (a.public_url !== null) { pm.expect(a.published_at).to.be.a('string'); }",
         "    });",
         "});",
