         "if (body.data.length > 0) {",
         "    pm.collectionVariables.set('assetGlobalId', body.data[0].global_id);",
         "} else {",
         "    console.warn('Nessun asset nel DB: le richieste sugli asset daranno 404.');",
         "}"
