5	namespace App\Http\Resources\Api;
6	
7	use App\Models\Product;
8	use AtrioTeam\DigitalHub\Pim\Enum\Type;
9	use Illuminate\Http\Request;
10	use Illuminate\Http\Resources\Json\JsonResource;
11	
12	/**
13	 * Payload di un Product per l'API esterna (roadmap #24).
14	 *
15	 * `name` è translatable: qui esce **già risolto** nella lingua della request
16	 * (`?locale=`), non come mappa lingua => valore.
17	 *
18	 * Prima entità esposta con attributi PIM popolati (`ProductAttributes`, via
19	 * `HasTechnicalAttributes`): il CMS non conosce lo schema, quindi qui gli
20	 * attributi escono **già risolti** — label tradotta, valore (enum già mappato
21	 * sulla label, translatable già nella lingua della request) e unità, uno per
22	 * chiave dello schema corrente del prodotto. Le chiavi senza valore non
23	 * compaiono (coerenti con lo strip degli orfani lato scrittura).
24	 *
25	 * @mixin Product
26	 */
27	class ProductResource extends JsonResource
28	{
29	    /**
30	     * @return array<string, mixed>
31	     */
32	    public function toArray(Request $request): array
33	    {
34	        return [
35	            // Chiave di join cross-sistema, non l'id: l'id locale dell'hub non
36	            // è un'identità stabile per il consumatore.
37	            'global_id' => $this->global_id,
38	            'name' => $this->name,
39	            'slug' => $this->slug,
40	            'category_global_id' => $this->category2?->global_id,
41	            'product_type_global_id' => $this->productType?->global_id,
42	            'attributes' => $this->resolveAttributes(),
43	            'updated_at' => $this->updated_at?->toIso8601String(),
44	        ];
45	    }
46	
47	    /**
48	     * @return array<string, array{label: string, value: mixed, unit: ?string}>
49	     */
50	    private function resolveAttributes(): array
51	    {
52	        $schema = $this->attributeSchema();
53	        if ($schema === null) {
54	            return [];
55	        }
56	
57	        $resolved = [];
58	
59	        foreach (array_keys($schema->attributes()) as $key) {
60	            $value = $this->attr($key);
61	            if ($value === null || $value === '') {
62	                continue;
63	            }
64	
65	            $type = $schema->getType($key);
66	            if ($type?->kind() === Type::Enum && is_string($value)) {
67	                $value = $this->attrOption($key, $value);
68	            }
69	
70	            $resolved[$key] = [
71	                'label' => $this->attrLabel($key),
72	                'value' => $value,
73	                'unit' => $type?->getUnit(),
74	            ];
75	        }
76	
77	        return $resolved;
78	    }
