1	<?php
2	
3	declare(strict_types=1);
4	
5	namespace App\Http\Resources\Api;
6	
7	use App\Http\Resources\Api\Concerns\ResolvesNameTranslations;
8	use App\Models\Product;
9	use AtrioTeam\DigitalHub\Pim\Enum\Type;
10	use Illuminate\Http\Request;
11	use Illuminate\Http\Resources\Json\JsonResource;
12	
13	/**
14	 * Payload di un Product per l'API esterna (roadmap #24).
15	 *
16	 * `name` è translatable: qui esce **già risolto** nella lingua della request
17	 * (`?locale=`), non come mappa lingua => valore — salvo `?with_translations=1`,
18	 * vedi [[ResolvesNameTranslations]].
19	 *
20	 * Prima entità esposta con attributi PIM popolati (`ProductAttributes`, via
21	 * `HasTechnicalAttributes`): il CMS non conosce lo schema, quindi qui gli
22	 * attributi escono **già risolti** — label tradotta, valore (enum già mappato
23	 * sulla label, translatable già nella lingua della request) e unità, uno per
24	 * chiave dello schema corrente del prodotto. Le chiavi senza valore non
25	 * compaiono (coerenti con lo strip degli orfani lato scrittura).
26	 *
27	 * @mixin Product
28	 */
29	class ProductResource extends JsonResource
30	{
31	    use ResolvesNameTranslations;
32	
33	    /**
34	     * @return array<string, mixed>
35	     */
36	    public function toArray(Request $request): array
37	    {
38	        $payload = [
39	            // Chiave di join cross-sistema, non l'id: l'id locale dell'hub non
40	            // è un'identità stabile per il consumatore.
41	            'global_id' => $this->global_id,
42	            'name' => $this->name,
43	            'slug' => $this->slug,
44	            'category_global_id' => $this->category2?->global_id,
45	            'product_type_global_id' => $this->productType?->global_id,
46	            'attributes' => $this->resolveAttributes(),
47	            'updated_at' => $this->updated_at?->toIso8601String(),
48	        ];
49	
50	        $translations = $this->nameTranslations($request);
51	        if ($translations !== null) {
52	            $payload['name_translations'] = $translations;
53	        }
54	
55	        return $payload;
56	    }
57	
58	    /**
59	     * @return array<string, array{label: string, value: mixed, unit: ?string}>
60	     */
61	    private function resolveAttributes(): array
62	    {
63	        $schema = $this->attributeSchema();
64	        if ($schema === null) {
65	            return [];
66	        }
67	
68	        $resolved = [];
69	
70	        foreach (array_keys($schema->attributes()) as $key) {
71	            $value = $this->attr($key);
72	            if ($value === null || $value === '') {
73	                continue;
74	            }
75	
76	            $type = $schema->getType($key);
77	            if ($type?->kind() === Type::Enum && is_string($value)) {
78	                $value = $this->attrOption($key, $value);
79	            }
80	
81	            $resolved[$key] = [
82	                'label' => $this->attrLabel($key),
83	                'value' => $value,
84	                'unit' => $type?->getUnit(),
85	            ];
86	        }
87	
88	        return $resolved;
89	    }
90	}
