3	declare(strict_types=1);
4	
5	namespace App\Http\Resources\Api;
6	
7	use App\Models\Product;
8	use AtrioTeam\DigitalHub\Pim\Enum\Type;
9	use Illuminate\Http\Request;
10	use Illuminate\Http\Resources\Json\JsonResource;
11	
12	/**
13	 * Payload di un Product per l'API esterna (roadmap #24).
14	 *
15	 * `name` è translatable: esce come mappa `locale => valore` con **tutte** le
16	 * lingue configurate (`config('digital-hub.locales')`), non risolto in una
17	 * sola — il CMS deve poter fare il mirror completo in un giro di sync solo.
18	 *
19	 * Prima entità esposta con attributi PIM popolati (`ProductAttributes`, via
20	 * `HasTechnicalAttributes`): il CMS non conosce lo schema, quindi qui gli
21	 * attributi escono **già risolti**, per tutte le lingue configurate:
22	 * - `label`: mappa locale => label tradotta dell'attributo;
23	 * - `value`: mappa locale => valore, se l'attributo è `translatable()` o
24	 *   `Enum` (il valore mostrato è la label dell'opzione, non la chiave
25	 *   canonica); altrimenti un valore singolo (numeri e date non dipendono
26	 *   dalla lingua);
27	 * - `unit`: singola, non dipende dalla lingua.
28	 * Le chiavi senza valore non compaiono (coerenti con lo strip degli orfani
29	 * lato scrittura).
30	 *
31	 * @mixin Product
32	 */
33	class ProductResource extends JsonResource
34	{
35	    /**
36	     * @return array<string, mixed>
37	     */
38	    public function toArray(Request $request): array
39	    {
40	        return [
41	            // Chiave di join cross-sistema, non l'id: l'id locale dell'hub non
42	            // è un'identità stabile per il consumatore.
43	            'global_id' => $this->global_id,
44	            'name' => $this->getTranslations('name'),
45	            'slug' => $this->slug,
46	            'category_global_id' => $this->category2?->global_id,
47	            'product_type_global_id' => $this->productType?->global_id,
48	            'attributes' => $this->resolveAttributes(),
49	            'updated_at' => $this->updated_at?->toIso8601String(),
50	        ];
51	    }
52	
53	    /**
54	     * @return array<string, array{label: array<string, string>, value: mixed, unit: ?string}>
55	     */
56	    private function resolveAttributes(): array
57	    {
58	        $schema = $this->attributeSchema();
59	        if ($schema === null) {
60	            return [];
61	        }
62	
63	        $locales = array_keys((array) config('digital-hub.locales', []));
64	        /** @var array<string, mixed> $rawValues */
65	        $rawValues = (array) $this->getAttribute($this->attributesColumn());
66	
67	        $resolved = [];
68	
69	        foreach ($schema->attributes() as $key => $type) {
70	            $raw = $rawValues[$key] ?? null;
71	            if ($this->isBlank($raw)) {
72	                continue;
73	            }
74	
75	            $value = $type->isTranslatable()
76	                ? $this->mapLocales($locales, fn (string $locale): mixed => $this->attr($key, $locale))
77	                : $this->attr($key);
78	
79	            if ($type->kind() === Type::Enum && is_string($value)) {
80	                $value = $this->mapLocales($locales, fn (string $locale): string => $this->attrOption($key, $value, $locale));
81	            }
82	
83	            $resolved[$key] = [
84	                'label' => $this->mapLocales($locales, fn (string $locale): string => $this->attrLabel($key, $locale)),
85	                'value' => $value,
86	                'unit' => $type->getUnit(),
87	            ];
88	        }
89	
90	        return $resolved;
91	    }
92	
93	    /**
94	     * @param list<string> $locales
95	     * @return array<string, mixed>
96	     */
97	    private function mapLocales(array $locales, callable $resolve): array
98	    {
99	        $map = [];
100	        foreach ($locales as $locale) {
101	            $map[$locale] = $resolve($locale);
102	        }
103	
104	        return $map;
105	    }
106	
107	    private function isBlank(mixed $raw): bool
108	    {
109	        if (is_array($raw)) {
110	            return $raw === [] || collect($raw)->every(static fn (mixed $v): bool => $v === null || $v === '');
111	        }
112	
113	        return $raw === null || $raw === '';
114	    }
115	}
