"description": "Category1 (Categoria) e Category2 (Collezione), sullo stesso pattern del tracer bullet designers: passano dall'ApiResourceRegistry, nessun controller dedicato. La Collezione espone in più category_global_id per ricostruire la gerarchia Categoria -> Collezione lato CMS.",
"item": [
 {
  "name": "Lista categorie",
  "event": [
   {
    "listen": "test",
    "script": {
     "type": "text/javascript",
     "exec": [
      "pm.test('200', () => pm.response.to.have.status(200));",
      "const body = pm.response.json();",
      "pm.test('ha data + meta di paginazione', () => {",
      "    pm.expect(body).to.have.property('data');",
      "    pm.expect(body.meta).to.have.property('total');",
      "});",
      "pm.test('ogni record espone il global_id come chiave di join', () => {",
      "    body.data.forEach(r => pm.expect(r.global_id, 'global_id').to.be.a('string'));",
      "});",
      "if (body.data.length > 0) {",
      "    pm.collectionVariables.set('category1GlobalId', body.data[0].global_id);",
      "} else {",
      "    console.warn('Nessuna categoria nel DB: le richieste per identifier daranno 404.');",
      "}"
     ]
    }
   }
  ],
  "request": {
   "method": "GET",
   "header": [
    {
     "key": "Accept",
     "value": "application/json"
    }
   ],
   "url": {
    "raw": "{{baseUrl}}/api/v1/categories-1",
    "host": [
     "{{baseUrl}}"
    ],
    "path": [
     "api",
     "v1",
     "categories-1"
    ]
   },
   "description": "Category1 (Categoria). `name` esce già risolto nella lingua di default dell'app, non come mappa translatable."
  }
 },
 {
  "name": "Singola categoria per global_id",
  "event": [
   {
    "listen": "test",
    "script": {
     "type": "text/javascript",
     "exec": [
      "pm.test('200', () => pm.response.to.have.status(200));",
      "pm.test('è il record richiesto', () => {",
      "    pm.expect(pm.response.json().data.global_id).to.eql(pm.collectionVariables.get('category1GlobalId'));",
      "});"
     ]
    }
   }
  ],
  "request": {
   "method": "GET",
   "header": [
    {
     "key": "Accept",
     "value": "application/json"
    }
   ],
   "url": {
    "raw": "{{baseUrl}}/api/v1/categories-1/{{category1GlobalId}}",
    "host": [
     "{{baseUrl}}"
    ],
    "path": [
     "api",
     "v1",
     "categories-1",
     "{{category1GlobalId}}"
    ]
   }
  }
 },
 {
  "name": "Lista collezioni",
  "event": [
   {
    "listen": "test",
    "script": {
     "type": "text/javascript",
     "exec": [
      "pm.test('200', () => pm.response.to.have.status(200));",
      "const body = pm.response.json();",
      "pm.test('ha data + meta di paginazione', () => {",
      "    pm.expect(body).to.have.property('data');",
      "    pm.expect(body.meta).to.have.property('total');",
      "});",
      "pm.test('ogni record espone global_id e category_global_id', () => {",
      "    body.data.forEach(r => {",
      "        pm.expect(r.global_id, 'global_id').to.be.a('string');",
      "        pm.expect(r, 'category_global_id').to.have.property('category_global_id');",
      "    });",
      "});",
      "if (body.data.length > 0) {",
      "    pm.collectionVariables.set('category2GlobalId', body.data[0].global_id);",
      "} else {",
      "    console.warn('Nessuna collezione nel DB: le richieste per identifier daranno 404.');",
      "}"
     ]
    }
   }
  ],
  "request": {
   "method": "GET",
   "header": [
    {
     "key": "Accept",
     "value": "application/json"
    }
   ],
   "url": {
    "raw": "{{baseUrl}}/api/v1/categories-2",
    "host": [
     "{{baseUrl}}"
    ],
    "path": [
     "api",
     "v1",
     "categories-2"
    ]
   },
   "description": "Category2 (Collezione). `category_global_id` è il global_id della Categoria (Category1) padre, per ricostruire la gerarchia lato CMS senza esporre l'id locale."
  }
 },
 {

attachment.snippet:
1	<?php
2	
3	declare(strict_types=1);
4	
5	namespace Tests\Feature\Api;
6	
7	use App\Models\Category1;
8	use App\Models\Category2;
9	use App\Models\Product;
10	use App\Models\ProductType;
11	use App\Pim\Schemas\ProductAttributes;
12	use AtrioTeam\DigitalHub\Pim\AttributeSchema;
13	use AtrioTeam\DigitalHub\Pim\Enum\Type;
14	use AtrioTeam\DigitalHub\Pim\TypeBuilder;
15	use Illuminate\Foundation\Testing\RefreshDatabase;
16	use Tests\TestCase;
17	
18	/**
19	 * API esterna di lettura consumata in pull dal CMS/client (roadmap #24).
20	 * Product è la prima entità esposta con attributi PIM popolati
21	 * (`HasTechnicalAttributes`): qui si verifica la risoluzione (label, valore
22	 * — enum già mappato sulla label, translatable già come mappa per lingua —,
23	 * unità) descritta in [[api-technical-attributes-resolution]].
24	 *
25	 * Tutto ciò che è translatable (name, label degli attributi, opzioni enum,
26	 * valori translatable() nello schema) esce come mappa locale => valore con
27	 * tutte le lingue di `config('digital-hub.locales')`, mai risolto in una
28	 * sola: il CMS fa il mirror completo in un solo giro di sync.
29	 */
30	class ProductApiTest extends TestCase
31	{
32	    use RefreshDatabase;
33	
34	    private const TOKEN = 'test-token';
35	
36	    protected function setUp(): void
37	    {
38	        parent::setUp();
39	
40	        config(['digital-hub.api.tokens' => 'atmosphera-admin:' . self::TOKEN]);
41	    }
42	
43	    public function test_it_rejects_a_request_without_a_valid_token(): void
44	    {
45	        $this->getJson('/api/v1/products')->assertUnauthorized();
46	    }
47	
48	    public function test_it_lists_products_with_category_and_product_type_global_id(): void
49	    {
50	        $category1 = Category1::create(['name' => ['it' => 'Sedute'], 'slug' => 'sedute']);
51	        $category2 = Category2::create(['name' => ['it' => 'Poltrone'], 'category_1_id' => $category1->id, 'slug' => 'poltrone']);
52	        $productType = ProductType::create(['name' => ['it' => 'Divano'], 'attribute_schema_class' => ProductAttributes::class]);
53	
54	        $product = Product::create([
55	            'name' => ['it' => 'Modulo A'],
56	            'slug' => 'modulo-a',
57	            'category_2_id' => $category2->id,
58	            'product_type_id' => $productType->id,
59	        ]);
60	
61	        $this->withToken(self::TOKEN)
62	            ->getJson('/api/v1/products')
63	            ->assertOk()
64	            ->assertJsonPath('data.0.global_id', $product->global_id)
65	            ->assertJsonPath('data.0.slug', 'modulo-a')
66	            ->assertJsonPath('data.0.category_global_id', $category2->global_id)
67	            ->assertJsonPath('data.0.product_type_global_id', $productType->global_id)
68	            ->assertJsonPath('meta.total', 1);
69	    }
70	
71	    public function test_it_exposes_name_as_a_map_with_all_configured_locales(): void
72	    {
73	        $category2 = $this->makeCategory2();
74	        $productType = $this->makeProductType();
75	
76	        Product::create([
77	            'name' => ['it' => 'Divano Blu', 'en' => 'Blue Sofa'],
78	            'slug' => 'divano-blu',
79	            'category_2_id' => $category2->id,
80	            'product_type_id' => $productType->id,
81	        ]);
82	
83	        $response = $this->withToken(self::TOKEN)
84	            ->getJson('/api/v1/products')
85	            ->assertOk();
86	
87	        /** @var array<string, string> $name */
88	        $name = $response->json('data.0.name');
89	        ksort($name);
90	        $this->assertSame(['en' => 'Blue Sofa', 'it' => 'Divano Blu'], $name);
91	    }
92	
93	    public function test_it_resolves_pim_attributes_with_label_value_and_unit_for_all_locales(): void
94	    {
95	        $category2 = $this->makeCategory2();
96	        $productType = $this->makeProductType();
97	
98	        $product = Product::create([
99	            'name' => ['it' => 'Divano'],
100	            'slug' => 'divano',
101	            'category_2_id' => $category2->id,
102	            'product_type_id' => $productType->id,
103	        ]);
104	        $product->setAttr('sku', 'DIV-001');
105	        $product->setAttr('weight', 42.5);
106	        $product->setAttr('taglia', 'L');
107	        $product->save();
108	
109	        $response = $this->withToken(self::TOKEN)
110	            ->getJson('/api/v1/products/' . $product->global_id)
111	            ->assertOk();
112	
113	        $response
114	            // Non translatable, non enum: valore singolo, non una mappa.
115	            ->assertJsonPath('data.attributes.sku.value', 'DIV-001')
116	            ->assertJsonPath('data.attributes.sku.label.it', 'SKU')
117	            ->assertJsonPath('data.attributes.sku.label.en', 'SKU')
118	            ->assertJsonPath('data.attributes.weight.value', 42.5)
119	            ->assertJsonPath('data.attributes.weight.unit', 'kg')
120	            ->assertJsonPath('data.attributes.weight.label.it', 'Peso')
121	            ->assertJsonPath('data.attributes.weight.label.en', 'Weight')
122	            // Enum: il valore è la label dell'opzione, una per lingua configurata.
123	            ->assertJsonPath('data.attributes.taglia.value.it', $product->attrOption('taglia', 'L', 'it'))
124	            ->assertJsonPath('data.attributes.taglia.value.en', $product->attrOption('taglia', 'L', 'en'))
125	            ->assertJsonMissingPath('data.attributes.year');
126	    }
127	
128	    public function test_it_resolves_translatable_pim_attribute_values_for_all_locales(): void
129	    {
130	        $category2 = $this->makeCategory2();
131	        $productType = ProductType::create([
132	            'name' => ['it' => 'Con descrizione'],
133	            'attribute_schema_class' => ProductApiTestTranslatableSchema::class,
134	        ]);
135	
136	        $product = Product::create([
137	            'name' => ['it' => 'Divano con descrizione'],
138	            'slug' => 'divano-con-descrizione',
139	            'category_2_id' => $category2->id,
140	            'product_type_id' => $productType->id,
141	        ]);
142	        $product->setAttr('description', ['it' => 'Bellissimo divano', 'en' => 'Beautiful sofa']);
143	        $product->save();
144	
145	        $this->withToken(self::TOKEN)
146	            ->getJson('/api/v1/products/' . $product->global_id)
147	            ->assertOk()
148	            ->assertJsonPath('data.attributes.description.value.it', 'Bellissimo divano')
149	            ->assertJsonPath('data.attributes.description.value.en', 'Beautiful sofa');
150	    }
151	
152	    public function test_it_returns_no_attributes_when_the_product_has_no_schema(): void
153	    {
154	        $category2 = $this->makeCategory2();
155	        $productType = ProductType::create(['name' => ['it' => 'Senza schema']]);
156	
157	        $product = Product::create([
158	            'name' => ['it' => 'Prodotto generico'],
159	            'slug' => 'prodotto-generico',
160	            'category_2_id' => $category2->id,
161	            'product_type_id' => $productType->id,
162	        ]);
163	
164	        $this->withToken(self::TOKEN)
