93	    public function test_it_resolves_pim_attributes_with_label_value_and_unit_for_all_locales(): void
94	    {
95	        $category2 = $this->makeCategory2();
96	        $productType = $this->makeProductType();
97	
98	        $product = Product::create([
99	            'name' => ['it' => 'Divano'],
100	            'slug' => 'divano',
101	            'category_2_id' => $category2->id,
102	            'product_type_id' => $productType->id,
103	        ]);
104	        $product->setAttr('sku', 'DIV-001');
105	        $product->setAttr('weight', 42.5);
106	        $product->setAttr('taglia', 'L');
107	        $product->save();
108	
109	        $response = $this->withToken(self::TOKEN)
110	            ->getJson('/api/v1/products/' . $product->global_id)
111	            ->assertOk();
