16	use Illuminate\Database\Eloquent\Model;
17	
18	class DigitalHubTableMacro
19	{
20	    public static function register(): void
21	    {
22	        // register a macro to perform some customization on all tables of the Digital Hub, like adding a default record action to open the edit page
23	        Table::macro('digitalHubTable', function (array $recordActions = []): Table {
24	            // $this is bound to the Table instance at runtime by Laravel's Macroable;
25	            // PHPStan cannot infer this statically for a macro closure.
26	            /** @var Table $this */
27	            // @phpstan-ignore-next-line varTag.variableNotFound, variable.undefined, argument.type
28	            return DigitalHubTableMacro::apply($this, $recordActions);
29	        });
30	    }
31	
32	    /**
33	     * Apply the Digital Hub customizations to a table.
34	     *
35	     * @param array<\Filament\Actions\Action> $recordActions Azioni di riga extra,
36	     *                                                       anteposte all'ActionGroup standard (es. ManageAssetsAction).
37	     */
38	    public static function apply(Table $table, array $recordActions = []): Table
39	    {
40	        $table->recordActions([
41	            ...$recordActions,
42	            ActionGroup::make([
43	                // la view è solo il ripiego per chi non può editare: a chi ha il
44	                // permesso di edit non va mostrata affatto. Nascondendola qui il
45	                // click sulla riga segue di conseguenza, senza toccare
46	                // `recordAction()`: il default di Filament cicla su
47	                // ['view', 'edit'] saltando le azioni nascoste, quindi cade su
48	                // edit da solo (ListRecords::table()).
49	                ViewAction::make()
50	                    ->visible(fn (Model $record): bool => ! static::canEditRecord($record))
51	                    ->slideOver()
52	                    ->modalWidth(Width::ScreenTwoExtraLarge),
53	                EditAction::make()->slideOver()->modalWidth(Width::ScreenTwoExtraLarge),
54	                DeleteAction::make(),
55	            ]),
56	        ])
57	        ->toolbarActions([
58	            BulkActionGroup::make([
59	                DeleteBulkAction::make()
60	                    ->modalHeading(__('digital-hub::common.delete_confirmation')),
61	            ]),
62	        ])
63	        ->defaultSort('sort')
64	        ->reorderable('sort')
65	        // evidenzia la riga il cui action modal (edit/view) è aperto via URL
66	        // (?tableAction=…&tableActionRecord=…, Livewire #[Url]): copre sia il
67	        // click da un risultato di ricerca globale (roadmap #23) sia il refresh
68	        // di una pagina con un'azione già aperta.
69	        ->recordClasses(function (Model $record): ?string {
70	            $highlightedKey = request()->query('tableActionRecord');
71	            $recordKey = $record->getKey();
72	
73	            if (! is_string($highlightedKey) || ! is_scalar($recordKey)) {
74	                return null;
75	            }
76	
77	            return ((string) $recordKey === $highlightedKey)
78	                ? '!bg-warning-50 dark:!bg-warning-400/10'
79	                : null;
80	        })
81	        ;
82	
83	        // customize filters
84	        $filters = $table->getFilters();
85	        if (count($filters) > 2) {
86	            $table->filtersFormColumns(3);
87	        }
88	
89	        // $table->filters($filters,);
90	
91	
92	        // convert the created_at column to proper timezone and format if it exists
93	        collect($table->getColumns())->each(function (Column $column): void {
94	            if ($column instanceof TextColumn && $column->getName() === 'created_at') {
95	                $column->dateTime('d/m/Y H:i', 'Europe/Rome')->sortable()->toggleable(isToggledHiddenByDefault: true);
96	            }
97	        });
98	
99	        return $table;
100	    }
101	
102	    /**
103	     * La macro non conosce il resource a cui appartiene la tabella: lo risolve
104	     * dal modello del record, così l'autorizzazione passa dalla stessa gate
105	     * (`Resource::canEdit()`) usata dall'EditAction della riga. Un
106	     * `Gate::allows('update')` diretto divergerebbe per i modelli senza
107	     * policy, dove Filament consente l'edit e il Gate lo nega: si vedrebbero
108	     * view ed edit insieme.
109	     *
110	     * Se il modello non è registrato come resource nel pannello corrente non
111	     * possiamo dire nulla sull'edit: la view resta visibile (ripiego sicuro).
112	     */
113	    protected static function canEditRecord(Model $record): bool
114	    {
115	        $resource = Filament::getModelResource($record);
116	
117	        return $resource !== null && $resource::canEdit($record);
118	    }
119	}
