1	<?php
2	
3	namespace AtrioTeam\DigitalHub\Pim\Filament\Tables;
4	
5	use Filament\Actions\ActionGroup;
6	use Filament\Actions\BulkActionGroup;
7	use Filament\Actions\DeleteAction;
8	use Filament\Actions\DeleteBulkAction;
9	use Filament\Actions\EditAction;
10	use Filament\Actions\ForceDeleteAction;
11	use Filament\Actions\ForceDeleteBulkAction;
12	use Filament\Actions\RestoreAction;
13	use Filament\Actions\RestoreBulkAction;
14	use Filament\Actions\ViewAction;
15	use Filament\Facades\Filament;
16	use Filament\Support\Enums\Width;
17	use Filament\Tables\Columns\Column;
18	use Filament\Tables\Columns\TextColumn;
19	use Filament\Tables\Filters\TrashedFilter;
20	use Filament\Tables\Table;
21	use Illuminate\Database\Eloquent\Model;
22	
23	class DigitalHubTableMacro
24	{
25	    public static function register(): void
26	    {
27	        // register a macro to perform some customization on all tables of the Digital Hub, like adding a default record action to open the edit page
28	        Table::macro('digitalHubTable', function (array $recordActions = []): Table {
29	            // $this is bound to the Table instance at runtime by Laravel's Macroable;
30	            // PHPStan cannot infer this statically for a macro closure.
31	            /** @var Table $this */
32	            // @phpstan-ignore-next-line varTag.variableNotFound, variable.undefined, argument.type
33	            return DigitalHubTableMacro::apply($this, $recordActions);
34	        });
35	    }
36	
37	    /**
38	     * Apply the Digital Hub customizations to a table.
39	     *
40	     * @param array<\Filament\Actions\Action> $recordActions Azioni di riga extra,
41	     *                                                       anteposte all'ActionGroup standard (es. ManageAssetsAction).
42	     */
43	    public static function apply(Table $table, array $recordActions = []): Table
44	    {
45	        $table->recordActions([
46	            ...$recordActions,
47	            ActionGroup::make([
48	                // la view è solo il ripiego per chi non può editare: a chi ha il
49	                // permesso di edit non va mostrata affatto. Nascondendola qui il
50	                // click sulla riga segue di conseguenza, senza toccare
51	                // `recordAction()`: il default di Filament cicla su
52	                // ['view', 'edit'] saltando le azioni nascoste, quindi cade su
53	                // edit da solo (ListRecords::table()).
54	                ViewAction::make()
55	                    ->visible(fn (Model $record): bool => ! static::canEditRecord($record))
56	                    ->slideOver()
57	                    ->modalWidth(Width::ScreenTwoExtraLarge),
58	                EditAction::make()->slideOver()->modalWidth(Width::ScreenTwoExtraLarge),
59	                DeleteAction::make(),
60	            ]),
61	        ])
62	        ->toolbarActions([
63	            BulkActionGroup::make([
64	                DeleteBulkAction::make()
65	                    ->modalHeading(__('digital-hub::common.delete_confirmation')),
66	            ]),
67	        ])
68	        ->defaultSort('sort')
69	        ->reorderable('sort')
70	        // evidenzia la riga il cui action modal (edit/view) è aperto via URL
71	        // (?tableAction=…&tableActionRecord=…, Livewire #[Url]): copre sia il
72	        // click da un risultato di ricerca globale (roadmap #23) sia il refresh
73	        // di una pagina con un'azione già aperta.
74	        ->recordClasses(function (Model $record): ?string {
75	            $highlightedKey = request()->query('tableActionRecord');
76	            $recordKey = $record->getKey();
77	
78	            if (! is_string($highlightedKey) || ! is_scalar($recordKey)) {
79	                return null;
80	            }
81	
82	            return ((string) $recordKey === $highlightedKey)
83	                ? '!bg-warning-50 dark:!bg-warning-400/10'
84	                : null;
85	        })
86	        ;
87	
88	        // customize filters
89	        $filters = $table->getFilters();
90	        if (count($filters) > 2) {
91	            $table->filtersFormColumns(3);
92	        }
93	
94	        // $table->filters($filters,);
95	
96	
97	        // convert the created_at column to proper timezone and format if it exists
98	        collect($table->getColumns())->each(function (Column $column): void {
99	            if ($column instanceof TextColumn && $column->getName() === 'created_at') {
100	                $column->dateTime('d/m/Y H:i', 'Europe/Rome')->sortable()->toggleable(isToggledHiddenByDefault: true);
101	            }
102	        });
103	
104	        return $table;
105	    }
106	
107	    /**
108	     * La macro non conosce il resource a cui appartiene la tabella: lo risolve
109	     * dal modello del record, così l'autorizzazione passa dalla stessa gate
110	     * (`Resource::canEdit()`) usata dall'EditAction della riga. Un
111	     * `Gate::allows('update')` diretto divergerebbe per i modelli senza
112	     * policy, dove Filament consente l'edit e il Gate lo nega: si vedrebbero
113	     * view ed edit insieme.
114	     *
115	     * Se il modello non è registrato come resource nel pannello corrente non
116	     * possiamo dire nulla sull'edit: la view resta visibile (ripiego sicuro).
117	     */
118	    protected static function canEditRecord(Model $record): bool
119	    {
120	        $resource = Filament::getModelResource($record);
121	
122	        return $resource !== null && $resource::canEdit($record);
123	    }
124	}
