1	<?php
2	
3	declare(strict_types=1);
4	
5	use Illuminate\Database\Migrations\Migration;
6	use Illuminate\Database\Schema\Blueprint;
7	use Illuminate\Support\Facades\Schema;
8	
9	return new class () extends Migration {
10	    /**
11	     * Entità esposte dall'API esterna (roadmap #24) che diventano soft-delete:
12	     * la cancellazione fisica non lascia più traccia nel sync incrementale, il
13	     * CMS/client non ha modo di sapere che un record è sparito.
