17	class RunSyncJob implements ShouldQueue
18	{
19	    use Dispatchable;
20	    use InteractsWithQueue;
21	    use Queueable;
22	    use SerializesModels;
23	
24	    // Un solo tentativo: il trigger è manuale (nessuna semantica di retry
25	    // automatico decisa nel design doc) e un retry contro un hub down si
26	    // limiterebbe a ritardare la visibilità del fallimento nella UI.
27	    public int $tries = 1;
28	
29	    public function __construct(private readonly int $syncRunId)
30	    {
31	    }
32	
33	    public function handle(): void
34	    {
35	        $run = SyncRun::findOrFail($this->syncRunId);
36	
37	        $run->update([
38	            'status' => SyncStatus::Running,
39	            'started_at' => now(),
40	        ]);
41	
42	        try {
43	            SyncRegistry::syncerFor($run->resource)->sync($run);
44	
45	            $run->update([
46	                'status' => SyncStatus::Success,
47	                'finished_at' => now(),
48	            ]);
49	        } catch (Throwable $e) {
50	            $run->update([
51	                'status' => SyncStatus::Failed,
52	                'error' => $e->getMessage(),
53	                'finished_at' => now(),
54	            ]);
55	
56	            // Il SyncRun riflette già il fallimento per la UI di dominio; il
57	            // job deve comunque fallire a livello di coda (failed_jobs),
58	            // altrimenti sparisce da qualunque monitoraggio infrastrutturale.
59	            throw $e;
60	        }
61	    }
62	}
