<?php

declare(strict_types=1);

use App\Sync\Category1Syncer;
use App\Sync\Category2Syncer;
use App\Sync\ProductSyncer;

/**
 * Override applicativo della config del package hub-sync (merge shallow:
 * dichiarando 'resources' qui si sostituisce l'intero blocco di default,
 * quindi vanno ripetute anche le chiavi che non si stanno personalizzando —
 * stesso caveat di atmosphera-hub/config/digital-hub.php).
 */
return [
    'base_url' => env('DIGITAL_HUB_URL'),

    // Token nella forma `consumer:token`, come registrato in
    // DIGITAL_HUB_API_TOKENS sull'hub.
    'token' => env('DIGITAL_HUB_API_TOKEN'),

    'per_page' => 100,

    // Risorse sincronizzabili dall'hub. Aggiungere qui una nuova entità
    // (tessuti, materiali, designer, ...) è la sola cosa da fare per
    // esporla nella UI di sync: vedi AtrioTeam\HubSync\SyncRegistry.
    'resources' => [
        'categories-1' => [
            'label' => 'Categorie',
            'syncer' => Category1Syncer::class,
        ],
        'categories-2' => [
            'label' => 'Collezioni',
            'syncer' => Category2Syncer::class,
        ],
        'products' => [
            'label' => 'Prodotti',
            'syncer' => ProductSyncer::class,
        ],
    ],
];
