17	 * roadmap #24): il syncer deve riconoscere `deleted_at` e soft-cancellare il
18	 * mirror locale invece di fare upsert dei suoi dati come se fosse un record
19	 * vivo qualsiasi.
20	 */
21	class ProductSyncerTest extends TestCase
22	{
23	    use RefreshDatabase;
24	
25	    protected function setUp(): void
26	    {
27	        parent::setUp();
28	
29	        config([
30	            'hub-sync.base_url' => 'https://hub.test',
31	            'hub-sync.token' => 'test-token',
32	        ]);
33	    }
