49	    {
50	        Product::create([
51	            'global_id' => 'products:1',
52	            'name' => ['it' => 'Divano Blu'],
53	            'slug' => 'divano-blu',
54	            'attributes' => [],
55	        ]);
56	
57	        $this->fakeHubResponse([
58	            $this->deletedItem('products:1'),
59	        ]);
60	
61	        $run = $this->run();
62	
63	        $this->assertSame(1, $run->fresh()->deleted_count);
64	        $this->assertSame(0, $run->fresh()->created_count);
65	        $this->assertSame(0, $run->fresh()->updated_count);
66	
67	        $product = Product::withTrashed()->where('global_id', 'products:1')->firstOrFail();
68	        $this->assertTrue($product->trashed());
69	    }
